/**
 * 负责鬼魂新娘婚礼、刀权捕获、工具及玩家关系知识的公共数据契约。
 * 输入为标识与已确认 inert 数据；输出为脱离结构／null，保持原字段、默认、限额及相关性。
 * 数据 owner 只构造序列化默认副本，不安装角色、持有 live 生命／回执或花费库存；
 * canKnife 是捕获时的知识布尔值，不是提交许可。浏览器反射不承诺 Proxy 零 trap，
 * Node 准入须先拒绝恶意对象，reader 不改变原阶段、资源或权限政策。
 */
import { copyEventData } from "../inert-event-data";
import type { Camp } from "../identity";

/** 唯一有来源的有限预设；扩展规则须有另一个具名政策，不从公共数据推导变体。 */
export const GHOST_BRIDE_POLICY = "awa_melbourne_ghost_bride_v1" as const;
export const GHOST_BRIDE_GOAL = "three_factions_elimination" as const;
export const GHOST_BRIDE_ROLE = "ghost_bride" as const;
/** 原可写成员知识联合；见证人没有伴侣聊天／库存字段，原 nullable 和 optional 保留。 */
export type WeddingActorView =
  | {
      policy: typeof GHOST_BRIDE_POLICY;
      member: "bride" | "groom";
      faction: Camp.ThirdParty;
      partnerId: number;
      witnessId: number | null;
      proposedWitnessId?: number;
      canKnife: boolean;
    }
  | {
      policy: typeof GHOST_BRIDE_POLICY;
      member: "witness";
      faction: Camp.ThirdParty;
      brideId: number;
      groomId: number;
      canKnife: boolean;
    };

export type WeddingStatus = "pending" | "active" | "paired" | "complete" | "failed" | "cancelled";
export interface GhostBrideState {
  policy: typeof GHOST_BRIDE_POLICY;
  remaining: 0 | 1;
  groomId: number | null;
}
export interface WeddingVote {
  actorId: number;
  targetId: number;
}
export interface WeddingSetup {
  policy: typeof GHOST_BRIDE_POLICY;
  status: WeddingStatus;
  actorId: number;
  groomId: number | null;
  witnessId: number | null;
  witnessVotes: WeddingVote[];
}
export interface WeddingPair {
  policy: typeof GHOST_BRIDE_POLICY;
  groupId: string;
  brideId: number;
  groomId: number;
  day: 1;
}
export interface WeddingGroup extends WeddingPair {
  witnessId: number;
}
export type WeddingKnifeOwner = "ordinary_pack" | "pair" | "witness" | "none";
export interface WeddingKnifeCapture {
  policy: typeof GHOST_BRIDE_POLICY;
  groupId: string;
  day: number;
  owner: WeddingKnifeOwner;
  actorIds: number[];
}
export type WeddingTool =
  | { name: "choose_bridegroom"; args: { target_id: number } }
  | { name: "choose_wedding_witness"; args: { target_id: number } }
  | { name: "speak_to_partner"; args: { text: string } }
  | { name: "wedding_kill_vote"; args: { target_id: number | null; abstain: boolean } }
  | { name: "kill_vote"; args: { target_id: number | null; abstain: boolean } };
function record(value: unknown): Record<string, unknown> | null {
  try {
    const p = copyEventData(value);
    return p && typeof p === "object" && !Array.isArray(p) ? (p as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}
function exact(p: Record<string, unknown>, names: readonly string[]): boolean {
  return Object.keys(p).length === names.length && names.every((k) => Object.hasOwn(p, k));
}
function id(value: unknown): value is number {
  return Number.isSafeInteger(value) && (value as number) > 0;
}
function groupId(value: unknown): value is string {
  return typeof value === "string" && /^ghost-bride:1:[1-9][0-9]*$/.test(value);
}
export function freshGhostBrideState(): GhostBrideState {
  return { policy: GHOST_BRIDE_POLICY, remaining: 1, groomId: null };
}
export function readGhostBrideState(value: unknown): GhostBrideState | null {
  const p = record(value);
  return p &&
    exact(p, ["policy", "remaining", "groomId"]) &&
    p.policy === GHOST_BRIDE_POLICY &&
    (p.remaining === 0 || p.remaining === 1) &&
    (p.groomId === null || id(p.groomId)) &&
    (p.remaining === 0 || p.groomId === null)
    ? (p as unknown as GhostBrideState)
    : null;
}
export function readWeddingPair(value: unknown): WeddingPair | null {
  const p = record(value);
  return p &&
    exact(p, ["policy", "groupId", "brideId", "groomId", "day"]) &&
    p.policy === GHOST_BRIDE_POLICY &&
    groupId(p.groupId) &&
    p.day === 1 &&
    id(p.brideId) &&
    id(p.groomId) &&
    p.brideId !== p.groomId &&
    p.groupId === `ghost-bride:1:${p.brideId}`
    ? (p as unknown as WeddingPair)
    : null;
}
export function readWeddingGroup(value: unknown): WeddingGroup | null {
  const p = record(value);
  if (!p || !exact(p, ["policy", "groupId", "brideId", "groomId", "day", "witnessId"])) return null;
  const { witnessId, ...pair } = p;
  return readWeddingPair(pair) &&
    id(witnessId) &&
    witnessId !== p.brideId &&
    witnessId !== p.groomId
    ? (p as unknown as WeddingGroup)
    : null;
}
export function readWeddingSetup(value: unknown): WeddingSetup | null {
  const p = record(value);
  if (
    !p ||
    !exact(p, ["policy", "status", "actorId", "groomId", "witnessId", "witnessVotes"]) ||
    p.policy !== GHOST_BRIDE_POLICY ||
    !id(p.actorId) ||
    !["pending", "active", "paired", "complete", "failed", "cancelled"].includes(
      p.status as string,
    ) ||
    (p.groomId !== null && (!id(p.groomId) || p.groomId === p.actorId)) ||
    (p.witnessId !== null &&
      (!id(p.witnessId) || p.witnessId === p.actorId || p.witnessId === p.groomId)) ||
    !Array.isArray(p.witnessVotes) ||
    p.witnessVotes.length > 2
  )
    return null;
  const votes = p.witnessVotes as unknown[];
  if (
    !votes.every((v, i) => {
      const a = record(v);
      return (
        a &&
        exact(a, ["actorId", "targetId"]) &&
        a.actorId === (i === 0 ? p.actorId : p.groomId) &&
        id(a.targetId) &&
        a.targetId !== p.actorId &&
        a.targetId !== p.groomId
      );
    })
  )
    return null;
  if (p.status === "pending" || p.status === "active") {
    if (p.groomId !== null || p.witnessId !== null || votes.length !== 0) return null;
  } else if (p.status === "complete") {
    if (
      p.groomId === null ||
      p.witnessId === null ||
      votes.length !== 2 ||
      !(votes as WeddingVote[]).every((v) => v.targetId === p.witnessId)
    )
      return null;
  } else {
    if (
      p.witnessId !== null ||
      (p.groomId === null && votes.length > 0) ||
      (p.status === "paired" && (p.groomId === null || votes.length > 1)) ||
      (votes.length === 2 &&
        (votes[0] as WeddingVote).targetId === (votes[1] as WeddingVote).targetId)
    )
      return null;
  }
  return p as unknown as WeddingSetup;
}
export function readWeddingKnifeCapture(value: unknown): WeddingKnifeCapture | null {
  const p = record(value);
  if (
    !p ||
    !exact(p, ["policy", "groupId", "day", "owner", "actorIds"]) ||
    p.policy !== GHOST_BRIDE_POLICY ||
    !groupId(p.groupId) ||
    !id(p.day) ||
    !["ordinary_pack", "pair", "witness", "none"].includes(p.owner as string) ||
    !Array.isArray(p.actorIds) ||
    !p.actorIds.every(id) ||
    new Set(p.actorIds).size !== p.actorIds.length
  )
    return null;
  const n = p.actorIds.length;
  return (
    p.owner === "none"
      ? n === 0
      : p.owner === "pair"
        ? n === 2
        : p.owner === "witness"
          ? n === 1
          : n >= 1 && n <= 3
  )
    ? (p as unknown as WeddingKnifeCapture)
    : null;
}
export function readWeddingTool(value: unknown): WeddingTool | null {
  const p = record(value),
    a = record(p?.args);
  if (!p || !exact(p, ["name", "args"]) || !a) return null;
  if (p.name === "choose_bridegroom" || p.name === "choose_wedding_witness")
    return exact(a, ["target_id"]) && id(a.target_id) ? (p as unknown as WeddingTool) : null;
  if (p.name === "speak_to_partner")
    return exact(a, ["text"]) && typeof a.text === "string" ? (p as unknown as WeddingTool) : null;
  if (p.name === "wedding_kill_vote" || p.name === "kill_vote")
    return exact(a, ["target_id", "abstain"]) &&
      ((a.abstain === true && a.target_id === null) || (a.abstain === false && id(a.target_id)))
      ? (p as unknown as WeddingTool)
      : null;
  return null;
}

export const GHOST_BRIDE_EVENT_TYPES = [
  "ghost_bride_pair_chosen",
  "ghost_bride_witness_vote",
  "ghost_bride_group_chosen",
  "ghost_bride_partner_chat",
  "ghost_bride_knife_captured",
  "ghost_bride_knife_vote",
  "ghost_bride_knife_resolved",
  "ghost_bride_partner_death",
] as const;
export function readGhostBrideEventFact(
  type: string,
  value: unknown,
): Record<string, unknown> | null {
  const p = record(value);
  if (!p || p.policy !== GHOST_BRIDE_POLICY || !groupId(p.groupId)) return null;
  if (type === "ghost_bride_pair_chosen") return readWeddingPair(p) ? p : null;
  if (type === "ghost_bride_group_chosen") return readWeddingGroup(p) ? p : null;
  if (type === "ghost_bride_knife_captured") return readWeddingKnifeCapture(p) ? p : null;
  if (type === "ghost_bride_witness_vote")
    return exact(p, ["policy", "groupId", "day", "actorId", "targetId", "voteIndex"]) &&
      p.day === 1 &&
      id(p.actorId) &&
      id(p.targetId) &&
      p.actorId !== p.targetId &&
      (p.voteIndex === 1 || p.voteIndex === 2)
      ? p
      : null;
  if (type === "ghost_bride_partner_chat")
    return exact(p, ["policy", "groupId", "day", "actorId", "recipientId", "text"]) &&
      id(p.day) &&
      id(p.actorId) &&
      id(p.recipientId) &&
      p.actorId !== p.recipientId &&
      typeof p.text === "string"
      ? p
      : null;
  if (type === "ghost_bride_knife_vote")
    return exact(p, ["policy", "groupId", "day", "owner", "actorId", "targetId", "abstain"]) &&
      id(p.day) &&
      id(p.actorId) &&
      ["ordinary_pack", "pair", "witness"].includes(p.owner as string) &&
      ((p.targetId === null && p.abstain === true) || (id(p.targetId) && p.abstain === false))
      ? p
      : null;
  if (type === "ghost_bride_knife_resolved") {
    const { targetId, ...capture } = p;
    return readWeddingKnifeCapture(capture) && (targetId === null || id(targetId)) ? p : null;
  }
  if (type === "ghost_bride_partner_death")
    return exact(p, ["policy", "groupId", "day", "actorId", "targetId", "phase"]) &&
      id(p.day) &&
      id(p.actorId) &&
      id(p.targetId) &&
      p.actorId !== p.targetId &&
      ["night", "day", "voting"].includes(p.phase as string)
      ? p
      : null;
  return null;
}

/**
 * Responsibility: copy inert event payload data for shared fact readers.
 * Input: JSON.parse data without revivers, or already proven inert values;
 * output: detached primitives, dense arrays and null-prototype records.
 * Limits and rejection codes preserve the original shared-reader contract:
 * depth three, caller-selected array bound (default 128), finite numbers and
 * enumerable data descriptors only. This browser-compatible reader may trigger
 * Proxy reflection; Node ingress must reject hostile proxies before calling it.
 * It grants no action authority and owns no domain state or filesystem access.
 */
export function copyEventData(value: unknown, maxArrayLength = 128, depth = 0): unknown {
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  )
    return value;
  if (!value || typeof value !== "object" || depth > 3) throw new Error("event_fact_not_data");
  const array = Array.isArray(value),
    prototype = Object.getPrototypeOf(value),
    descriptors = Object.getOwnPropertyDescriptors(value);
  if (
    (array
      ? prototype !== Array.prototype
      : prototype !== Object.prototype && prototype !== null) ||
    Object.getOwnPropertySymbols(value).length
  )
    throw new Error("event_fact_not_plain");
  const result: Record<string, unknown> = Object.create(null);
  for (const [key, field] of Object.entries(descriptors)) {
    if (array && key === "length") continue;
    if (!field.enumerable || !Object.hasOwn(field, "value")) throw new Error("event_fact_accessor");
    result[key] = copyEventData(field.value, maxArrayLength, depth + 1);
  }
  if (!array) return result;
  const length = descriptors.length?.value;
  if (
    !Number.isSafeInteger(length) ||
    length < 0 ||
    length > maxArrayLength ||
    Object.keys(result).length !== length
  )
    throw new Error("event_fact_array");
  return Array.from({ length }, (_, index) => {
    if (!Object.hasOwn(result, String(index))) throw new Error("event_fact_sparse");
    return result[String(index)];
  });
}

/**
 * 负责通过原婚礼 authority 顺序收集鬼魂新娘的新郎／见证人选择。
 * 输入为只读板子政策、当前阵容和引擎请求；输出为设置事实或中断结果，回合由原 owner 关闭。
 * 此协调器不改规则或绕过身份、失败及期限校验，每次请求保留原 new 点与 opaque turn。
 * 构造依赖只晚读实际类，base只传对象引用；内层turn与外层setup仍各按原 finally 关闭，不补交失败选择。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { GHOST_BRIDE_POLICY, readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import {
  Phase,
  type World,
  type GameEvent,
  type ActionProvider,
  type ActionStage,
  type ToolName,
} from "../../../../core/domain";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import {
  beginWeddingSetup,
  openWeddingTurn,
  closeWeddingTurn,
  closeWeddingSetup,
  ghostBrideReady,
  weddingSetup,
  weddingPair,
  weddingGroup,
  weddingActorView,
  weddingNightCapture,
  authorizedWeddingTurn,
  commitWeddingTool,
  takeWeddingChat,
} from "./authority";
/** 装配依赖晚提供类，每次仍 new 原参数的工厂；opaque 原回合仍由 authority 校验，不启用 fallback。 */
export async function executeWeddingTurn(input: {
  world: World;
  gateway: ToolGateway;
  events: GameEvent[];
  provider: ActionProvider;
  day: number;
  actorId: number;
  kind: "bridegroom" | "chat" | "witness" | "knife";
  tool: ToolName;
  stage: ActionStage;
  isCurrent: () => boolean;
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort };
}): Promise<void> {
  const { world, gateway, events, provider, day, actorId, kind, tool, stage, isCurrent } = input;
  const scope = openWeddingTurn(world, kind, actorId, day, isCurrent);
  try {
    const view = weddingActorView(world, actorId);
    // opaque turn 已开、原 view 已读后才查类；失败仍在原 try 内关闭此 turn。
    const request = new input.construction.requestFactory(world, events, day).create({
      phase: Phase.Night,
      actorId,
      allowedTools: [tool],
      stage,
      requiresAction: true,
      summary: { key: "request.summary.night_action" },
      context: {
        allow_fallback: false,
        action_failure_policy: "error",
        ...(kind === "witness" && view && "proposedWitnessId" in view
          ? { proposedWitnessId: view.proposedWitnessId }
          : {}),
      },
    });
    const raw = await provider.getAction(request);
    if (!authorizedWeddingTurn(world, actorId, Phase.Night, day, scope))
      throw new Error("ghost_bride_turn_revoked");
    const call = readWeddingTool(raw);
    if (!call || call.name !== tool) throw new Error("ghost_bride_required_action_missing");
    const valid = gateway.validateAndSanitize(world, actorId, call, {
      phase: Phase.Night,
      day,
      ghostBrideScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall) throw new Error("ghost_bride_action_invalid");
    const committed = commitWeddingTool(scope, call);
    const pair = weddingPair(world);
    if (!pair) throw new Error("ghost_bride_pair_unavailable");
    if (kind === "bridegroom" && committed)
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_pair_chosen",
        payload: { ...pair },
        audience: Object.freeze([pair.brideId, pair.groomId].sort((a, b) => a - b)),
      });
    if (kind === "witness" && call.name === "choose_wedding_witness") {
      const votes = weddingSetup(world)!.witnessVotes;
      if (votes.some((v) => v.actorId === actorId && v.targetId === call.args.target_id))
        events.push({
          timestamp: Date.now(),
          type: "ghost_bride_witness_vote",
          payload: {
            policy: GHOST_BRIDE_POLICY,
            groupId: pair.groupId,
            day: 1,
            actorId,
            targetId: call.args.target_id,
            voteIndex: votes.length as 1 | 2,
          },
          audience: Object.freeze([]),
        });
      const group = weddingGroup(world);
      if (committed && group)
        events.push({
          timestamp: Date.now(),
          type: "ghost_bride_group_chosen",
          payload: { ...group },
          audience: Object.freeze(
            [group.brideId, group.groomId, group.witnessId].sort((a, b) => a - b),
          ),
        });
    }
    if (
      kind === "knife" &&
      committed &&
      (call.name === "kill_vote" || call.name === "wedding_kill_vote")
    ) {
      const capture = weddingNightCapture(world, day)!;
      if (capture.owner === "none") throw new Error("ghost_bride_knife_owner_invalid");
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_knife_vote",
        payload: {
          policy: GHOST_BRIDE_POLICY,
          groupId: pair.groupId,
          day,
          owner: capture.owner,
          actorId,
          targetId: call.args.target_id,
          abstain: call.args.abstain,
        },
        audience: Object.freeze(capture.owner === "ordinary_pack" ? [] : [actorId]),
      });
      if (capture.owner === "ordinary_pack")
        events.push({
          timestamp: Date.now(),
          type: "wolf_kill_vote_cast",
          payload: { actorId, targetId: call.args.target_id, abstain: call.args.abstain },
          audience: Object.freeze([...capture.actorIds].sort((a, b) => a - b)),
        });
    }
    const actualDisagreement =
      kind === "witness" &&
      call.name === "choose_wedding_witness" &&
      weddingSetup(world)!.witnessVotes.some(
        (v) => v.actorId === actorId && v.targetId === call.args.target_id,
      );
    const recordCommit = () =>
      safeRecordLogicOp({
        scope: "gateway",
        op: "validate_tool_call",
        actorId,
        phase: Phase.Night,
        status: "ok",
        input: { tool: call.name, args: call.args },
      });
    if (kind !== "chat" && (committed || actualDisagreement)) recordCommit();
    if (!committed) throw new Error("ghost_bride_action_commit_failed");
    if (kind === "chat") {
      const message = takeWeddingChat(scope);
      if (!message) throw new Error("ghost_bride_chat_delivery_revoked");
      recordCommit();
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_partner_chat",
        payload: { policy: GHOST_BRIDE_POLICY, groupId: pair.groupId, ...message },
        audience: Object.freeze([message.actorId, message.recipientId].sort((a, b) => a - b)),
      });
    }
  } finally {
    closeWeddingTurn(scope);
  }
}
export class GhostBrideSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    /** 保存引用；下方 base 的展开不会读取真正构造器。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (ghostBrideReady(this.world)) return true;
    const setup = weddingSetup(this.world);
    if (!setup || setup.status !== "pending" || day !== 1)
      throw new Error("ghost_bride_setup_unavailable");
    try {
      beginWeddingSetup(this.world, config, isCurrent);
      const base = {
        world: this.world,
        gateway: this.gateway,
        events: this.events,
        provider,
        day,
        isCurrent,
        // 普通数据字段仅传依赖对象；...base 不触发其 requestFactory getter。
        construction: this.construction,
      };
      await executeWeddingTurn({
        ...base,
        actorId: setup.actorId,
        kind: "bridegroom",
        tool: "choose_bridegroom",
        stage: "ghost_bride_groom",
      });
      const pair = weddingPair(this.world)!;
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "chat",
          tool: "speak_to_partner",
          stage: "ghost_bride_chat",
        });
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "witness",
          tool: "choose_wedding_witness",
          stage: "ghost_bride_witness",
        });
      if (!isCurrent() || !ghostBrideReady(this.world))
        throw new Error("ghost_bride_setup_revoked");
      return true;
    } finally {
      closeWeddingSetup(this.world, isCurrent() ? "failed" : "cancelled");
    }
  }
}

/**
 * 负责鬼魂新娘伴侣聊天及婚约狼刀请求。输入为绑定婚约夜、原参与者和已验证选择；输出为聊天结算、刀口与事实。
 * 婚约权威拥有原付款、投票和关闭；本阶段保 await 后真实复验，不令旧 pending 请求重新有效。
 * priority=150／400 的原顺序保持，过期普通／婚约狼刀清理归规则组合，历史票不重建或退款。
 */
import { StatusMark, COMPONENT } from "../../../../core/domain";
import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import type { NightStageHandler } from "../../stages/night/contracts";
import { executeWeddingTurn } from "./setup";
import {
  weddingPair,
  weddingNightCapture,
  resolveWeddingKnife,
  weddingKnifeCurrent,
} from "./authority";
export const WEDDING_CHAT_STAGE: NightStageHandler = {
  id: "ghost_bride_chat",
  priority: 150,
  async execute(ctx) {
    const day = ctx.currentDay(),
      pair = weddingPair(ctx.world);
    if (
      day === 1 ||
      !pair ||
      ![pair.brideId, pair.groomId].every(
        (id) => ctx.world.getComponent(id, COMPONENT.Alive)?.alive === true,
      )
    )
      return;
    for (const actorId of [pair.brideId, pair.groomId])
      await executeWeddingTurn({
        world: ctx.world,
        gateway: ctx.toolGateway,
        events: ctx.events,
        provider: ctx.actionProvider,
        day,
        actorId,
        kind: "chat",
        tool: "speak_to_partner",
        stage: "ghost_bride_chat",
        isCurrent: ctx.isCurrent,
        construction: ctx,
      });
  },
};
export const WEDDING_KNIFE_STAGE: NightStageHandler = {
  id: "ghost_bride_knife",
  priority: 400,
  async execute(ctx) {
    const day = ctx.currentDay(),
      capture = weddingNightCapture(ctx.world, day);
    if (!capture) throw new Error("ghost_bride_capture_missing");
    for (const actorId of capture.actorIds) {
      const tool = capture.owner === "ordinary_pack" ? "kill_vote" : "wedding_kill_vote";
      await executeWeddingTurn({
        world: ctx.world,
        gateway: ctx.toolGateway,
        events: ctx.events,
        provider: ctx.actionProvider,
        day,
        actorId,
        kind: "knife",
        tool,
        stage: capture.owner === "ordinary_pack" ? "wolf_vote" : "ghost_bride_knife",
        isCurrent: ctx.isCurrent,
        construction: ctx,
      });
      // 原投票仍由婚约权威保存，本阶段不从事实或目标重建票表。
    }
    const targetId = resolveWeddingKnife(ctx.world, day);
    ctx.events.push({
      timestamp: Date.now(),
      type: "ghost_bride_knife_resolved",
      payload: { ...capture, actorIds: [...capture.actorIds], targetId },
      audience: Object.freeze(
        capture.owner === "ordinary_pack" ? [] : [...capture.actorIds].sort((a, b) => a - b),
      ),
    });
    ctx.state.wolfTarget = targetId;
    if (targetId !== null && weddingKnifeCurrent(ctx.world, day, targetId)) {
      const marks = ctx.ensureMarks(targetId),
        life = ctx.world.getComponent(targetId, COMPONENT.Alive)!;
      marks.add(StatusMark.WolfKillMark);
      ctx.state.wolfTargetScope = { targetId, life, version: aliveLifeVersion(life)!, marks };
    }
  },
};

/**
 * 负责鬼新娘本次夜间开夜事实与晚交接；输入为延迟 World／事件、日期和原 setup ownership，
 * 输出保持原刀源捕获与关闭。owned 的捕获失败仍须关闭，不增加取得成功的前置守卫。
 * 经理原两个终止调用保持；已付婚约、setup、源验证、死亡规则及阶段推进由各原 owner 负责。
 * 规则依据：docs/rules/awa-melbourne-ghost-bride-v1.md。
 */
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../../core/domain/world";
import { captureWeddingKnife, closeWeddingNight } from "./authority";

export interface WeddingNightRuntime {
  readonly world: World;
  readonly events: GameEvent[];
}

export const weddingNightTerminal = Object.freeze({
  close(world: World): void {
    closeWeddingNight(world);
  },
});

export class WeddingNightUnit {
  /** 经理接收同一所有权实例，原终止函数仍使用调用时的参数。 */
  readonly close = weddingNightTerminal.close;

  private transferred = false;

  constructor(
    private readonly runtime: WeddingNightRuntime,
    private readonly owned: boolean,
  ) {}

  open(day: number, isCurrent: () => boolean): void {
    const capture = captureWeddingKnife(this.runtime.world, day, isCurrent);
    this.runtime.events.push({
      timestamp: Date.now(),
      type: "ghost_bride_knife_captured",
      payload: { ...capture, actorIds: [...capture.actorIds] },
      audience: Object.freeze([]),
    });
  }

  transferToManager(owned: boolean): void {
    this.transferred = owned;
  }

  abortIfOwned(): void {
    if (this.owned && !this.transferred) closeWeddingNight(this.runtime.world);
  }
}
